import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { addLocalDays, createTranslator, epochOf, formatInstant, formatLocalWeekdayDay, localDateInZone, localDaysBetween, localMinuteOfDay, zoneCity } from "@dcortex/canvas-format";
import type { ApiClient } from "../api/client.js";
import { DeskNotesPopup, type NotesRead } from "../desk/DeskNotesPopup.js";
import type { ShiftHandoverResponse } from "../desk/briefModel.js";
import type { FlightPick } from "../desk/flightPick.js";
import { mergeNotes, type MemosResponse } from "../desk/notesModel.js";
import { LaunchpadFlightCard } from "../launchpad/LaunchpadFlightCard.js";
import { messages } from "../i18n/messages.js";
import { opsRank, opsStatusTitle, rawNocRanks, StatusDialog } from "./horizonStatus.js";
import { greetingKey, STATUS_ORDER, unavailableLabelKey } from "../launchpad/boardModel.js";
import { LAUNCHPAD_POLL_MS } from "../launchpad/horizonModel.js";
import type { HorizonItem, HorizonRailCard, HorizonResponse } from "../launchpad/types.js";

/** Ops Launchpad (knowledge-base/features/launchpad.md). The horizon snapshot as count marks.
 * Title, day controls, and the time rail share one box. Delay, summary, and Up next stack under it.
 * Zoom fills a fixed viewport the way the legacy board does: − shows more hours, Expand grows the lanes. */

const LANES = ["checkin", "uncrewed", "connection", "delayed", "ftl"] as const;
const DAY_OFFSETS = [-3, -2, -1, 0, 1, 2, 3, 4];
const HEAD = 36;
const PAD = 24;
const VIEWPORT_FALLBACK = 800;
/** Compact lane pitch, and the expanded pitch (legacy's ~2.5×). */
const LANE_COMPACT = 48;
const LANE_EXPANDED = 140;

interface ZoomLevel {
  visibleHours: number;
  windowMins: number;
  label: "hours" | "quarterDay" | "halfDay" | "day" | "twoDays" | "threeDays" | "week";
  tickHours: number;
  spanDays?: number;
}

const ZOOMS: readonly ZoomLevel[] = [
  { visibleHours: 8, windowMins: 12, label: "hours", tickHours: 2 },
  { visibleHours: 16, windowMins: 24, label: "hours", tickHours: 3 },
  { visibleHours: 24, windowMins: 360, label: "quarterDay", tickHours: 6 },
  { visibleHours: 48, windowMins: 720, label: "halfDay", tickHours: 12 },
  { visibleHours: 24, windowMins: 1440, label: "day", tickHours: 24 },
  { visibleHours: 48, windowMins: 1440, label: "twoDays", tickHours: 24, spanDays: 2 },
  { visibleHours: 72, windowMins: 1440, label: "threeDays", tickHours: 24, spanDays: 3 },
  { visibleHours: 168, windowMins: 1440, label: "week", tickHours: 24, spanDays: 7 },
];

function spanOf(zoom: ZoomLevel): number {
  return zoom.spanDays ?? 1;
}

function isHorizon(body: unknown): body is HorizonResponse {
  if (body == null || typeof body !== "object") return false;
  const row = body as HorizonResponse;
  return typeof row.date === "string" && typeof row.now === "string" && typeof row.zone === "string"
    && Array.isArray(row.wire) && Array.isArray(row.rail) && Array.isArray(row.queue) && Array.isArray(row.banks);
}

function routeOf(item: { detail: Record<string, unknown> }): string {
  const { dep, arr } = item.detail;
  return typeof dep === "string" && typeof arr === "string" ? `${dep}→${arr}` : "";
}

function flightOf(item: { label: string; detail: Record<string, unknown> }): string {
  return typeof item.detail.flight === "string" && item.detail.flight !== "" ? item.detail.flight : item.label;
}

function hhmm(minute: number): string {
  const wrapped = ((minute % 1440) + 1440) % 1440;
  return `${String(Math.floor(wrapped / 60)).padStart(2, "0")}:${String(wrapped % 60).padStart(2, "0")}`;
}

/** The axis starts at midnight of the loaded window. Scale is the viewport divided by the hours in view. */
function axisOf(viewportW: number, visibleHours: number, spanHours: number): { pxPerHour: number; width: number } {
  const inView = Math.min(Math.max(visibleHours, 1), Math.max(spanHours, 1));
  const pxPerHour = Math.max(viewportW - PAD * 2, 1) / inView;
  return { pxPerHour, width: PAD * 2 + spanHours * pxPerHour };
}

function xOfMins(mins: number, pxPerHour: number): number {
  return PAD + (mins / 60) * pxPerHour;
}

function toneOf(items: readonly { hoursUntil: number; severity: HorizonItem["severity"] }[]): string {
  if (items.every((item) => item.hoursUntil < 0)) return "past";
  if (items.some((item) => item.severity === "crit")) return "crit";
  if (items.some((item) => item.severity === "warn")) return "warn";
  return "watch";
}

interface Mark {
  domain?: HorizonItem["domain"];
  severity: HorizonItem["severity"];
  anchor: string;
  overdue: boolean;
  hoursUntil: number;
  /** Minutes from midnight of the loaded window's first day. */
  atMins: number;
  bankId?: string | null;
  label: string;
  detail: HorizonItem["detail"];
}

interface Bubble { key: string; left: number; tone: string; items: Mark[] }

function onAxis(anchor: string, start: string, zone: string, days: number): number | null {
  const diff = localDaysBetween(start, localDateInZone(epochOf(anchor), zone));
  if (diff < 0 || diff >= days) return null;
  return diff * 1440 + localMinuteOfDay(anchor, zone);
}

/** Legality marks use the anchors the desk row already carries. */
function rowMarks(snap: HorizonResponse, key: "ftl"): Array<Omit<Mark, "atMins">> {
  const row = snap.rows?.find((entry) => entry.key === key);
  if (!row || row.status !== "ok") return [];
  const now = epochOf(snap.now);
  const marks: Array<Omit<Mark, "atMins">> = [];
  for (const cell of row.cells) {
    cell.items.forEach((item, index) => {
      const hoursUntil = (epochOf(item.anchor) - now) / 3_600_000;
      const flight = typeof item.detail.flight === "string" && item.detail.flight !== "" ? item.detail.flight : String(index);
      marks.push({
        severity: item.severity,
        anchor: item.anchor,
        overdue: hoursUntil < 0,
        hoursUntil,
        ...(cell.bankId !== "" ? { bankId: cell.bankId } : {}),
        label: `${key}:${flight}:${cell.bankId}:${index}`,
        detail: item.detail,
      });
    });
  }
  return marks;
}

function clusterLane(items: readonly Mark[], xOf: (mins: number) => number, windowMins: number): Bubble[] {
  const sorted = [...items].sort((a, b) => a.atMins - b.atMins);
  if (windowMins >= 360) {
    const buckets = new Map<number, Mark[]>();
    for (const item of sorted) {
      const idx = Math.floor(item.atMins / windowMins);
      const list = buckets.get(idx) ?? [];
      list.push(item);
      buckets.set(idx, list);
    }
    return [...buckets.entries()].sort((a, b) => a[0] - b[0]).map(([idx, group]) => ({
      key: group[0]!.label,
      left: xOf(idx * windowMins + windowMins / 2),
      tone: toneOf(group),
      items: group,
    }));
  }
  const out: Bubble[] = [];
  for (const item of sorted) {
    const prev = out.at(-1);
    const last = prev?.items.at(-1);
    if (prev && last && item.atMins - last.atMins <= windowMins) {
      prev.items.push(item);
      prev.left = prev.items.reduce((sum, row) => sum + xOf(row.atMins), 0) / prev.items.length;
      prev.tone = toneOf(prev.items);
    } else {
      out.push({ key: item.label, left: xOf(item.atMins), tone: toneOf([item]), items: [item] });
    }
  }
  return out;
}

export function Launchpad({ client, onPresentation }: { client: ApiClient; onPresentation?: () => void }) {
  const ctx = client.presentation() ?? { timezone: "UTC", locale: "en", currency: "USD" };
  const t = createTranslator(ctx.locale, messages);
  const [params, setParams] = useSearchParams();
  const date = params.get("date") ?? "";
  const [snap, setSnap] = useState<HorizonResponse | null>(null);
  const [extra, setExtra] = useState<HorizonResponse[]>([]);
  const [zoomIdx, setZoomIdx] = useState(1);
  const [rangeDays, setRangeDays] = useState(1);
  const [expanded, setExpanded] = useState(false);
  const [viewportW, setViewportW] = useState(VIEWPORT_FALLBACK);
  const [mode, setMode] = useState<"timeline" | "banks">("timeline");
  const [failed, setFailed] = useState(false);
  const [queueOpen, setQueueOpen] = useState(false);
  const [delayOpen, setDelayOpen] = useState(false);
  const [open, setOpen] = useState<{ key: string; top: number; left: number } | null>(null);
  const [reload, setReload] = useState(0);
  const [statusOpen, setStatusOpen] = useState<{ key: string; times: string[] | null } | null>(null);
  const [flightPick, setFlightPick] = useState<FlightPick | null>(null);
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [paletteQuery, setPaletteQuery] = useState("");
  const [notesOpen, setNotesOpen] = useState(false);
  const [notes, setNotes] = useState<NotesRead>({ status: "loading" });
  const scrollerRef = useRef<HTMLDivElement>(null);
  const followNow = useRef(true);
  const holdCenter = useRef<number | null>(null);
  const seenDate = useRef<string | null>(null);
  const zoom = ZOOMS[zoomIdx] ?? ZOOMS[1]!;
  const banksOk = spanOf(zoom) <= 1;

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setPaletteOpen((current) => !current);
      }
      if (event.key === "Escape") {
        setPaletteOpen(false);
        setFlightPick(null);
        setStatusOpen(null);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  useEffect(() => {
    if (!banksOk) setMode("timeline");
  }, [banksOk]);

  useEffect(() => {
    followNow.current = true;
  }, [date]);

  useEffect(() => {
    let live = true;
    let polling = false; // a poll tick is skipped while the last read is still out, so a slow read never stacks
    const load = () => {
      if (polling) return;
      polling = true;
      const q = date ? `?date=${encodeURIComponent(date)}` : "";
      void client.get<unknown>(`/api/read/horizon${q}`).then(async (body) => {
        if (!live) return;
        if (!isHorizon(body)) {
          setSnap(null);
          setExtra([]);
          setFailed(true);
          return;
        }
        const more: HorizonResponse[] = [];
        if (rangeDays > 1) {
          const rest = await Promise.all(Array.from({ length: rangeDays - 1 }, (_, index) => {
            const day = addLocalDays(body.date, index + 1);
            return client.get<unknown>(`/api/read/horizon?date=${encodeURIComponent(day)}`);
          }));
          if (!live) return;
          for (const row of rest) if (isHorizon(row)) more.push(row);
        }
        setFailed(false);
        setSnap(body);
        setExtra(more);
      }).catch((err: unknown) => {
        if (!live) return;
        if (err instanceof Error && err.message === "unauthenticated") return;
        setSnap(null);
        setExtra([]);
        setFailed(true);
      }).finally(() => {
        polling = false;
      });
    };
    load();
    const timer = setInterval(() => {
      if (document.visibilityState === "visible") load();
    }, LAUNCHPAD_POLL_MS);
    return () => {
      live = false;
      clearInterval(timer);
    };
  }, [client, date, rangeDays, reload]);

  useEffect(() => {
    if (snap) onPresentation?.();
  }, [snap, onPresentation]);

  const notesDate = date || snap?.date || "";
  useEffect(() => {
    if (!notesDate) return;
    let live = true;
    void Promise.all([
      client.get<unknown>(`/api/read/flight-memos?date=${encodeURIComponent(notesDate)}`).catch(() => undefined),
      client.get<unknown>("/api/read/shift-handover").catch(() => undefined),
    ]).then(([memos, brief]) => {
      if (!live) return;
      const memoBody = isMemos(memos) ? memos : undefined;
      const briefBody = isBrief(brief) ? brief : undefined;
      setNotes({
        status: "ok",
        ...(memoBody ? { memos: memoBody } : { memosFailed: true }),
        ...(briefBody ? { brief: briefBody } : { briefFailed: true }),
      });
    });
    return () => {
      live = false;
    };
  }, [client, notesDate, reload]);

  const notesCount = useMemo(() => {
    if (notes.status !== "ok" || notes.memosFailed || notes.briefFailed) return null;
    return mergeNotes({
      ...(notes.memos ? { memos: notes.memos } : {}),
      ...(notes.brief ? { brief: notes.brief } : {}),
    }, t).length;
  }, [notes, t]);

  const today = snap ? localDateInZone(epochOf(snap.now), snap.zone) : "";
  const start = snap?.date ?? "";
  const loaded = snap ? [snap, ...extra] : [];
  const queue = snap?.queue ?? [];
  const head = queue[0];
  const nowMinute = snap ? localMinuteOfDay(snap.now, snap.zone) : 0;
  const laneH = expanded ? LANE_EXPANDED : LANE_COMPACT;
  const spanHours = rangeDays * 24;
  const { pxPerHour, width } = axisOf(viewportW, zoom.visibleHours, spanHours);
  const xAt = (mins: number) => xOfMins(mins, pxPerHour);
  const showNow = snap ? (() => {
    const diff = localDaysBetween(start, today);
    return diff >= 0 && diff < rangeDays;
  })() : false;
  const nowX = showNow ? xAt(localDaysBetween(start, today) * 1440 + nowMinute) : 0;
  const height = HEAD + LANES.length * laneH;

  const locate = (item: Omit<Mark, "atMins">): Mark | null => {
    if (!snap) return null;
    const atMins = onAxis(item.anchor, start, snap.zone, rangeDays);
    return atMins == null ? null : { ...item, atMins };
  };
  const wire: Mark[] = [];
  for (const row of loaded) {
    for (const item of row.wire) {
      const placed = locate(item);
      if (placed) wire.push(placed);
    }
  }
  const deskFtl: Mark[] = [];
  for (const row of loaded) {
    for (const item of rowMarks(row, "ftl")) {
      const placed = locate(item);
      if (placed) deskFtl.push(placed);
    }
  }

  useLayoutEffect(() => {
    const el = scrollerRef.current;
    if (!el) return;
    const apply = () => {
      const next = el.clientWidth;
      if (next > 0) setViewportW((current) => (current === next ? current : next));
    };
    apply();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(apply);
    observer.observe(el);
    return () => observer.disconnect();
  }, [snap]);

  useEffect(() => {
    const el = scrollerRef.current;
    if (!el || !snap) return;
    const dayChanged = seenDate.current !== snap.date;
    seenDate.current = snap.date;
    const center = holdCenter.current;
    holdCenter.current = null;
    const place = () => {
      if (dayChanged && !showNow) {
        el.scrollLeft = 0;
        return;
      }
      if (followNow.current && showNow) {
        const view = el.clientWidth || viewportW;
        el.scrollLeft = Math.max(0, nowX - view * 0.2);
        return;
      }
      if (center != null) {
        const view = el.clientWidth || viewportW;
        el.scrollLeft = Math.max(0, xOfMins(center, pxPerHour) - view / 2);
      }
    };
    place();
    const frame = requestAnimationFrame(place);
    return () => cancelAnimationFrame(frame);
  }, [snap, nowX, showNow, viewportW, zoomIdx, mode, rangeDays, pxPerHour]);
  let days = today ? DAY_OFFSETS.map((offset) => addLocalDays(today, offset)) : [];
  if (snap && !days.includes(snap.date)) days = [...days, snap.date].sort();

  const pickDay = (day: string) => {
    setRangeDays(1);
    setParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set("date", day);
      return next;
    });
  };

  const stepZoom = (dir: 1 | -1) => {
    const next = Math.max(0, Math.min(zoomIdx + dir, ZOOMS.length - 1));
    if (next === zoomIdx) return;
    const el = scrollerRef.current;
    if (el && !(followNow.current && showNow)) {
      const view = el.clientWidth || viewportW;
      holdCenter.current = ((el.scrollLeft + view / 2 - PAD) / pxPerHour) * 60;
    }
    const span = spanOf(ZOOMS[next]!);
    setZoomIdx(next);
    if (dir > 0) setRangeDays((current) => Math.max(current, span));
  };

  const chip = (day: string): string => {
    if (day === today) return t("desk.date.today");
    if (today && day === addLocalDays(today, 1)) return t("desk.date.tomorrow");
    return formatLocalWeekdayDay(day, ctx.locale);
  };

  const laneOf = (domain: (typeof LANES)[number]): readonly Mark[] =>
    domain === "ftl" ? deskFtl : wire.filter((item) => item.domain === domain);

  const ticks: Array<{ key: string; x: number; label: string }> = [];
  if (snap && mode === "timeline") {
    for (let hour = zoom.tickHours; hour < spanHours; hour += zoom.tickHours) {
      if (hour % 24 === 0) continue;
      ticks.push({ key: String(hour), x: xAt(hour * 60), label: hhmm(hour * 60) });
    }
  }
  if (snap && mode === "banks") {
    for (let day = 0; day < rangeDays; day++) {
      for (const bank of snap.banks) {
        const end = bank.endMinute != null && bank.endMinute > bank.startMinute ? bank.endMinute : bank.startMinute + 60;
        const x = xAt(day * 1440 + (bank.startMinute + end) / 2);
        if (x < 0 || x > width) continue;
        ticks.push({ key: `${day}-${bank.id}`, x, label: bankLabel(bank.id) });
      }
    }
  }

  const bubbles = (domain: (typeof LANES)[number]): Bubble[] => {
    if (mode === "banks") {
      const groups = new Map<string, Mark[]>();
      for (const item of laneOf(domain)) {
        const day = Math.floor(item.atMins / 1440);
        const key = `${day}:${item.bankId ?? ""}`;
        const list = groups.get(key) ?? [];
        list.push(item);
        groups.set(key, list);
      }
      return [...groups.values()].map((group) => {
        const at = group.reduce((sum, item) => sum + item.atMins, 0) / group.length;
        return { key: group[0]!.label, left: xAt(at), tone: toneOf(group), items: group };
      });
    }
    return clusterLane(laneOf(domain), xAt, zoom.windowMins);
  };

  const openBubble = open && snap
    ? LANES.flatMap((domain) => bubbles(domain)).find((bubble) => bubble.key === open.key)
    : undefined;

  return (
    <section className="ops-horizon" data-testid="launchpad-screen" aria-label={t("ops.launchpad.horizon")}>
      {failed && !snap && <p role="alert">{t("ops.launchpad.failed")}</p>}
      {!failed && !snap && (
        <div className="ops-horizon-loading" data-testid="launchpad-loading" role="status" aria-live="polite" aria-busy="true">
          <p className="ops-loading-note">{t("ops.launchpad.loading")}</p>
          <div className="ops-horizon-board" aria-hidden="true">
            {LANES.map((lane) => (
              <span key={lane} className="ops-skel ops-skel--block" />
            ))}
          </div>
        </div>
      )}
      {snap && (
        <>
          <div className="ops-horizon-greet">
              <div>
                <h2>{t(greetingKey(nowMinute))}</h2>
                <div className="ops-horizon-sub">{[client.presentation()?.customerName, zoneCity(snap.zone, client.presentation()), formatInstant(snap.now, ctx, { style: "time" })].filter(Boolean).join(" · ")}</div>
              </div>
              <div className="ops-horizon-actions">
                <button type="button" onClick={() => setNotesOpen(true)}>
                  {t("desk.notes.button")}
                  {notesCount !== null && notesCount > 0 && <span className="ops-horizon-badge">{notesCount > 99 ? "99+" : notesCount}</span>}
                </button>
                <button type="button" data-testid="launchpad-search" onClick={() => setPaletteOpen(true)}>{t("launchpad.board.search")}</button>
                <button type="button" onClick={() => setReload((n) => n + 1)}>{t("launchpad.board.refresh")}</button>
              </div>
            </div>
          <div className="ops-horizon-split">
          <div className="ops-horizon-main" data-testid="launchpad-column">
          <section className="ops-horizon-board" data-testid="launchpad-board">
            <div className="ops-horizon-head">
              <h1>{t("ops.launchpad.horizon")}</h1>
              <span className="ops-horizon-live">{t("ops.launchpad.live")} · {hhmm(nowMinute)}</span>
            </div>
            <div className="ops-horizon-tools" data-testid="launchpad-toolbar">
              <div className="ops-horizon-days" role="group" aria-label={t("ops.launchpad.pickDate")}>
                {days.map((day) => (
                  <button key={day} type="button" data-testid={`launchpad-day-${day}`} aria-pressed={day === snap.date} onClick={() => pickDay(day)}>
                    {chip(day)}
                  </button>
                ))}
                <label className="ops-horizon-cal">
                  <input
                    type="date"
                    data-testid="launchpad-date"
                    aria-label={t("ops.launchpad.pickDate")}
                    value={snap.date}
                    onChange={(event) => {
                      if (event.target.value) pickDay(event.target.value);
                    }}
                  />
                </label>
              </div>
              <div className="ops-horizon-modes" role="group">
                <button type="button" aria-pressed={mode === "timeline"} onClick={() => setMode("timeline")}>{t("ops.launchpad.timeline")}</button>
                <button type="button" aria-pressed={mode === "banks"} disabled={!banksOk} onClick={() => setMode("banks")}>{t("ops.launchpad.banks")}</button>
              </div>
              <div className="ops-horizon-stepper">
                <button type="button" aria-label={t("ops.launchpad.zoomOut")} disabled={zoomIdx >= ZOOMS.length - 1} onClick={() => stepZoom(1)}>−</button>
                <span data-testid="launchpad-zoom-label">{t(`ops.launchpad.zoom.${zoom.label}`)}</span>
                <button type="button" aria-label={t("ops.launchpad.zoomIn")} disabled={zoomIdx <= 0} onClick={() => stepZoom(-1)}>+</button>
              </div>
              <button type="button" className="ops-horizon-expand" aria-pressed={expanded} onClick={() => setExpanded((current) => !current)}>
                {expanded ? t("ops.launchpad.collapse") : t("ops.launchpad.expand")}
              </button>
            </div>
            <div className="ops-horizon-wire" data-testid="launchpad-wire">
              <div className="ops-horizon-gutter" style={{ height }}>
                {LANES.map((domain, index) => (
                  <div key={domain} className="ops-horizon-lane-name" data-testid={`launchpad-lane-${domain}`} style={{ top: HEAD + index * laneH + laneH / 2 - 8 }}>
                    {t(`ops.launchpad.lane.${domain}`)}
                  </div>
                ))}
              </div>
              <div
                className="ops-horizon-scroll"
                ref={scrollerRef}
                data-testid="launchpad-scroll"
                data-viewport={viewportW}
                onScroll={(event) => {
                  if (!showNow) return;
                  const el = event.currentTarget;
                  const view = el.clientWidth || viewportW;
                  const target = Math.max(0, nowX - view * 0.2);
                  if (Math.abs(el.scrollLeft - target) > 16) followNow.current = false;
                }}
              >
                <div className={`ops-horizon-plot${expanded ? " expanded" : ""}`} data-testid="launchpad-plot" style={{ height, width }}>
                  {Array.from({ length: rangeDays }, (_, day) => snap.banks.map((bank, index) => {
                    const end = bank.endMinute ?? bank.startMinute;
                    const left = xAt(day * 1440 + bank.startMinute);
                    let right = xAt(day * 1440 + end);
                    if (right <= left) right = xAt(day * 1440 + end + 1440);
                    const x = Math.max(0, left);
                    const w = Math.min(width, right) - x;
                    if (w <= 0) return null;
                    return <div key={`${day}-${bank.id}`} className={index % 2 ? "ops-horizon-band alt" : "ops-horizon-band"} style={{ left: x, width: w, top: HEAD }} />;
                  }))}
                  {mode === "timeline" && Array.from({ length: rangeDays }, (_, day) => (
                    <span key={`day-${day}`} className="ops-horizon-daytick" data-testid={`launchpad-daytick-${day}`} style={{ left: xAt(day * 1440) }}>
                      {formatLocalWeekdayDay(addLocalDays(start, day), ctx.locale)}
                    </span>
                  ))}
                  {ticks.map((mark) => (
                    <span key={mark.key} className="ops-horizon-tick" style={{ left: mark.x }}>{mark.label}</span>
                  ))}
                  {showNow && <div className="ops-horizon-past" style={{ top: HEAD, width: Math.max(0, Math.min(width, nowX)) }} />}
                  {LANES.map((domain, index) => (
                    <div key={domain} className="ops-horizon-line" style={{ top: HEAD + index * laneH + laneH / 2 }} />
                  ))}
                  {showNow && (
                    <div className="ops-horizon-now" style={{ left: nowX }} data-testid="launchpad-now">
                      <span className="ops-horizon-nowtag">{t("launchpad.now")} {hhmm(nowMinute)}</span>
                    </div>
                  )}
                  {LANES.map((domain, index) => bubbles(domain).map((bubble) => (
                    <button
                      key={bubble.key}
                      type="button"
                      className={`ops-horizon-dot ${bubble.tone}`}
                      data-testid={`launchpad-pill-${bubble.items[0]?.label ?? bubble.key}`}
                      style={{ left: bubble.left, top: HEAD + index * laneH + laneH / 2 - 13 }}
                      aria-label={tipLines(bubble.items, snap.zone, t).map((line) => line.detail !== "" ? `${line.title} — ${line.detail}` : line.title).join(", ")}
                      onMouseEnter={(event) => {
                        const rect = event.currentTarget.getBoundingClientRect();
                        setOpen({ key: bubble.key, top: rect.top, left: rect.left + rect.width / 2 });
                      }}
                      onMouseLeave={() => setOpen((current) => current?.key === bubble.key ? null : current)}
                      onFocus={(event) => {
                        const rect = event.currentTarget.getBoundingClientRect();
                        setOpen({ key: bubble.key, top: rect.top, left: rect.left + rect.width / 2 });
                      }}
                      onBlur={() => setOpen((current) => current?.key === bubble.key ? null : current)}
                      onClick={() => {
                        setOpen(null);
                        const at = domain === "checkin" || domain === "ftl"
                          ? [...new Set(bubble.items.map((item) => hhmm(localMinuteOfDay(item.anchor, snap.zone))))]
                          : null;
                        setStatusOpen({ key: domain, times: at });
                      }}
                    >
                      {bubble.items.length}
                    </button>
                  )))}
                </div>
              </div>
            </div>
            <div className="ops-horizon-legend">
              <span><i className="crit" />{t("ops.launchpad.actNow")}</span>
              <span><i className="warn" />{t("ops.launchpad.keepEye")}</span>
            </div>
          </section>
          <section className="ops-horizon-delay" data-testid="launchpad-delay" aria-label={t("ops.launchpad.delayRail")}>
            <button type="button" className="ops-horizon-next-toggle" aria-expanded={delayOpen} onClick={() => setDelayOpen((current) => !current)}>
              <span className="ops-horizon-up">{t("ops.launchpad.delayRail")}</span>
              <span className="ops-horizon-rank">{delayedRows(snap).length}</span>
              <span className="ops-horizon-chevron" aria-hidden="true">{delayOpen ? "▾" : "▸"}</span>
            </button>
            {delayOpen && (
              <div className="ops-horizon-delay-list">
                {delayedRows(snap).map((item) => (
                  <button key={item.key} type="button" className="ops-horizon-delay-row" onClick={() => item.pick && setFlightPick(item.pick)}>
                    <span>{item.flight}{item.route ? ` ${item.route}` : ""}</span>
                    {item.late != null && <span>{t("ops.launchpad.minutesLate", { n: String(item.late) })}</span>}
                  </button>
                ))}
              </div>
            )}
          </section>
          <section className="ops-horizon-summary">
            <h2>{t("ops.launchpad.summary")}</h2>
            <p>
              {head
                ? t("ops.launchpad.summaryBody", { n: String(queue.length), flight: `${flightOf(head)}${routeOf(head) ? ` ${routeOf(head)}` : ""}` })
                : t("ops.launchpad.summaryClear")}
            </p>
            {(snap.unplaced?.undated ?? 0) > 0 && (
              <p className="ops-horizon-note" data-testid="launchpad-undated">{t("ops.launchpad.undated", { n: snap.unplaced.undated })}</p>
            )}
          </section>
          <footer className="ops-horizon-next" data-testid="launchpad-next">
            <button type="button" className="ops-horizon-next-toggle" aria-expanded={queueOpen} onClick={() => setQueueOpen((current) => !current)}>
              <span className="ops-horizon-up">{t("ops.launchpad.upNext")}</span>
              <span className="ops-horizon-count">{queue.length}</span>
              {head && (
                <span>
                  {t("ops.launchpad.nextItem", {
                    when: hhmm(localMinuteOfDay(head.anchor, snap.zone)),
                    flight: `${flightOf(head)}${routeOf(head) ? ` · ${routeOf(head)}` : ""}`,
                  })}
                  {head.overdue ? ` · ${t("launchpad.overdue")}` : ""}
                </span>
              )}
              <span className="ops-horizon-rank">{t("ops.launchpad.rankBy")}</span>
              <span className="ops-horizon-chevron" aria-hidden="true">{queueOpen ? "▾" : "▸"}</span>
            </button>
            {queueOpen && (
              <ul>
                {queue.map((item) => (
                  <li key={item.label} data-testid={`launchpad-next-${item.label}`}>
                    <b>{flightOf(item)}{routeOf(item) ? ` ${routeOf(item)}` : ""}</b>
                    <span>{hhmm(localMinuteOfDay(item.anchor, snap.zone))}{item.overdue ? ` · ${t("launchpad.overdue")}` : ""}</span>
                  </li>
                ))}
              </ul>
            )}
          </footer>
          </div>
          <aside className="ops-horizon-status" aria-label={t("launchpad.rail")}>
            {STATUS_ORDER.filter((key) => key !== "absences" && snap.rail.some((card) => card.key === key)).map((key) => {
              const card = snap.rail.find((row) => row.key === key);
              return (
                <button key={key} type="button" className="ops-horizon-kpi" data-testid={`launchpad-status-${key}`} onClick={() => setStatusOpen({ key, times: null })}>
                  <span className="ops-horizon-kpi-title">{opsStatusTitle(key, t)}</span>
                  <span className="ops-horizon-kpi-value">{card?.status === "ok" ? card.count ?? 0 : t(unavailableLabelKey(card?.reason))}</span>
                  <span className="ops-horizon-kpi-foot">{card?.status === "ok" ? t("ops.launchpad.onDay") : card?.reason === "failed" || card?.reason === "not_permitted" ? t(unavailableLabelKey(card.reason)) : t("ops.launchpad.sourceOff")}</span>
                </button>
              );
            })}
          </aside>
          </div>
          {statusOpen && (
            <StatusDialog key={statusOpen.key} t={t} client={client} snap={snap} statusKey={statusOpen.key} times={statusOpen.times} onClose={() => setStatusOpen(null)} onFlight={setFlightPick} />
          )}
          {flightPick && (
            <LaunchpadFlightCard client={client} pick={flightPick} date={snap.date} zone={snap.zone} ctx={ctx} t={t} onClose={() => setFlightPick(null)} />
          )}
          {paletteOpen && (
            <SearchPalette
              t={t}
              rail={snap.rail}
              query={paletteQuery}
              onQuery={setPaletteQuery}
              onClose={() => setPaletteOpen(false)}
              onOpen={(key) => { setPaletteOpen(false); setPaletteQuery(""); setStatusOpen({ key, times: null }); }}
            />
          )}
          {notesOpen && (
            <DeskNotesPopup
              read={notes}
              date={notesDate}
              banks={snap.banks.map((bank) => ({ id: bank.id, startMinute: bank.startMinute, endMinute: bank.endMinute ?? bank.startMinute }))}
              ctx={ctx}
              t={t}
              onClose={() => setNotesOpen(false)}
            />
          )}
          {open && openBubble && (
            <WireTip bubble={openBubble} zone={snap.zone} top={open.top} left={open.left} t={t} />
          )}
        </>
      )}
    </section>
  );
}

function bankLabel(id: string): string {
  const match = /^B(\d+)$/.exec(id);
  return match ? `Bank ${match[1]}` : id;
}

/** The stored label is an opaque key. The card is the time, the lane, and the detail fields. */
function WireTip({ bubble, zone, top, left, t }: {
  bubble: Bubble;
  zone: string;
  top: number;
  left: number;
  t: (key: string, params?: Record<string, string | number>) => string;
}) {
  const items = [...bubble.items].sort((a, b) => a.atMins - b.atMins);
  const first = items[0];
  if (!first) return null;
  const domain = kindOf(first);
  const lines = tipLines(items, zone, t);
  const bankIds = [...new Set(items.flatMap((item) => (item.bankId ? [item.bankId] : [])))];
  const bank = bankIds.length === 1 ? bankLabel(bankIds[0]!) : "";
  const shown = lines.slice(0, 4);
  const more = lines.length - shown.length;
  const count = domain === "uncrewed" ? openSeats(items) : items.length;
  const head = [bank, t(`ops.launchpad.lane.${domain}`), String(count)].filter((part) => part !== "").join(" · ");
  return (
    <div className="ops-horizon-pop" role="tooltip" style={{ top, left }}>
      <div className="tt-head">
        <span className={`tt-time ${bubble.tone}`}>{hhmm(localMinuteOfDay(first.anchor, zone))}</span>
        <span>{head}</span>
      </div>
      {shown.map((line, index) => (
          <div className="tt-row" key={`${line.title}:${index}`}>
            <b>{line.title}</b>
            {line.detail !== "" ? ` — ${line.detail}` : ""}
          </div>
      ))}
      {more > 0 && <div className="tt-more">{t("ops.launchpad.tip.more", { n: String(more) })}</div>}
    </div>
  );
}

function kindOf(item: Mark): string {
  return item.domain ?? field(item.detail, "kind");
}

function field(detail: Record<string, unknown>, key: string): string {
  const value = detail[key];
  return typeof value === "string" ? value : "";
}

function fieldNum(detail: Record<string, unknown>, key: string): number | null {
  const value = detail[key];
  return typeof value === "number" ? value : null;
}

function readable(label: string): string {
  return /^(uncrewed|connection|checkin|delayed|ftl):/.test(label) ? "" : label;
}

function joinTime(lead: string, time: string, rest: string): string {
  const head = [lead, time].filter((part) => part !== "").join(" ");
  return [head, rest].filter((part) => part !== "").join(" · ");
}

interface SeatBit { code: string; short: number | null }

function seatsOf(detail: Record<string, unknown>): SeatBit[] {
  const seats = detail.seats;
  if (Array.isArray(seats)) {
    return seats.filter((row): row is Record<string, unknown> => !!row && typeof row === "object").map((row) => ({
      code: field(row, "code") || field(row, "positionCode"),
      short: fieldNum(row, "short"),
    })).filter((row) => row.code !== "");
  }
  const code = field(detail, "positionCode");
  return code === "" ? [] : [{ code, short: fieldNum(detail, "short") }];
}

function groupUncrewed(items: readonly Mark[]): Mark[] {
  const out: Mark[] = [];
  const index = new Map<string, number>();
  for (const item of items) {
    const flight = field(item.detail, "flight");
    const dep = field(item.detail, "dep");
    const arr = field(item.detail, "arr");
    const route = flight !== "" || dep !== "" || arr !== ""
      ? `${flight}|${dep}|${arr}`
      : field(item.detail, "pairingId") || field(item.detail, "pairingKey") || item.label;
    const key = `${route}|${Math.floor(item.atMins)}`;
    const at = index.get(key);
    const bits = seatsOf(item.detail);
    if (at == null) {
      index.set(key, out.length);
      out.push({ ...item, detail: { ...item.detail, seats: bits } });
      continue;
    }
    const prev = out[at]!;
    prev.detail = { ...prev.detail, seats: [...seatsOf(prev.detail), ...bits] };
  }
  return out;
}

function openSeats(items: readonly Mark[]): number {
  return items.reduce((sum, item) => {
    const seats = seatsOf(item.detail);
    if (seats.length === 0) return sum + 1;
    return sum + seats.reduce((n, seat) => n + (seat.short != null && seat.short > 0 ? seat.short : 1), 0);
  }, 0);
}

function tipLines(items: readonly Mark[], zone: string, t: (key: string, params?: Record<string, string | number>) => string): Array<{ title: string; detail: string }> {
  const rows = items[0] && kindOf(items[0]) === "uncrewed" ? groupUncrewed(items) : items;
  return rows.map((item) => tipOf(item, hhmm(localMinuteOfDay(item.anchor, zone)), t));
}

function tipOf(item: Mark, time: string, t: (key: string, params?: Record<string, string | number>) => string): { title: string; detail: string } {
  const detail = item.detail;
  const kind = kindOf(item);
  if (kind === "uncrewed") {
    const flight = field(detail, "flight");
    const dep = field(detail, "dep");
    const arr = field(detail, "arr");
    const seats = seatsOf(detail);
    const raw = rawNocRanks(seats.map((seat) => seat.code));
    const what = seats.map((seat) => {
      const rank = opsRank(seat.code, raw);
      if (!rank) return "";
      const n = seat.short != null && seat.short > 0 ? seat.short : 1;
      return `${rank} −${n}`;
    }).filter((part) => part !== "").join(", ");
    const route = dep !== "" && arr !== "" ? `${dep} → ${arr}` : "";
    const lead = [flight, time].filter((part) => part !== "").join(" ");
    return { title: [lead, route].filter((part) => part !== "").join(" · "), detail: what !== "" ? t("ops.launchpad.tip.needs", { what }) : "" };
  }
  if (kind === "connection") {
    const inbound = field(detail, "inboundFlight");
    const outbound = field(detail, "outboundFlight");
    const station = field(detail, "connectionStation");
    const hop = [inbound, outbound].filter((part) => part !== "").join(" → ");
    const named = readable(item.label);
    const title = hop !== ""
      ? `${hop} ${time}${station !== "" ? ` · ${station}` : ""}`
      : joinTime(named, time, named === "" ? field(detail, "pairingRoute") : "");
    const status = t(item.severity === "crit" ? "ops.launchpad.tip.critical" : "ops.launchpad.tip.warning");
    const actual = fieldNum(detail, "actualGapMins");
    const required = fieldNum(detail, "requiredMins");
    const gap = actual != null && required != null ? t("ops.launchpad.tip.gap", { actual: String(actual), required: String(required) }) : "";
    const line = [t("ops.launchpad.tip.connection", { status }), gap].filter((part) => part !== "").join(" · ");
    return { title, detail: line };
  }
  if (kind === "checkin") {
    const who = [field(detail, "position"), field(detail, "displayName")].filter((part) => part !== "").join(" ");
    const late = fieldNum(detail, "lateMinutes");
    const parts = [
      ...(who !== "" ? [t("ops.launchpad.tip.notCheckedIn", { who })] : []),
      ...(late != null ? [t("ops.launchpad.minutesLate", { n: String(late) })] : []),
    ];
    return { title: joinTime(field(detail, "flight") || readable(item.label), time, routeOf(item)), detail: parts.join(" · ") };
  }
  if (kind === "delayed") {
    const late = fieldNum(detail, "delayMinutes");
    return {
      title: joinTime(field(detail, "flight") || readable(item.label), time, routeOf(item)),
      detail: late != null ? t("ops.launchpad.minutesLate", { n: String(late) }) : "",
    };
  }
  const who = [field(detail, "role"), field(detail, "displayName")].filter((part) => part !== "").join(" · ");
  const current = fieldNum(detail, "currentValue");
  const limit = fieldNum(detail, "limitValue");
  const unit = field(detail, "unit");
  const headroom = current != null && limit != null ? `${current}/${limit}${unit !== "" ? ` ${unit}` : ""}` : "";
  const line = [field(detail, "ruleCode"), headroom, field(detail, "windowType")].filter((part) => part !== "").join(" · ");
  const title = who !== "" ? who : joinTime(field(detail, "flight") || readable(item.label), time, routeOf(item));
  return { title, detail: line };
}

function isMemos(body: unknown): body is MemosResponse {
  return !!body && typeof body === "object" && Array.isArray((body as MemosResponse).memos);
}

function isBrief(body: unknown): body is ShiftHandoverResponse {
  return !!body && typeof body === "object" && Array.isArray((body as ShiftHandoverResponse).sections);
}

function railOff(key: string, rail: readonly HorizonRailCard[]): boolean {
  const card = rail.find((row) => row.key === key);
  return !card || card.status !== "ok";
}

function text(value: unknown): string {
  return typeof value === "string" && value !== "" ? value : "";
}

function pickOf(item: { label: string; detail: Record<string, unknown> }): FlightPick | undefined {
  const flight = text(item.detail.outboundFlight) || text(item.detail.flight) || (item.label.includes(":") ? "" : item.label);
  const dep = text(item.detail.connectionStation) || text(item.detail.dep);
  const arr = text(item.detail.arr);
  if (!flight || !dep || !arr) return undefined;
  const legId = text(item.detail.legId);
  return { flight, dep, arr, ...(legId ? { legId } : {}) };
}

function delayedRows(snap: HorizonResponse): Array<{ key: string; flight: string; route: string; late: number | null; pick?: FlightPick }> {
  const fromWire = snap.wire.filter((item) => item.domain === "delayed").map((item) => ({
    key: item.label,
    flight: flightOf(item),
    route: routeOf(item),
    late: typeof item.detail.delayMinutes === "number" ? item.detail.delayMinutes : null,
    ...(() => { const pick = pickOf(item); return pick ? { pick } : {}; })(),
  }));
  if (fromWire.length > 0) return fromWire;
  const row = snap.rows?.find((entry) => entry.key === "delayed");
  if (!row || row.status !== "ok") return [];
  return row.cells.flatMap((cell, cellIndex) => cell.items.map((item, index) => ({
    key: `${cell.bankId}:${cellIndex}:${index}`,
    flight: typeof item.detail.flight === "string" && item.detail.flight !== "" ? item.detail.flight : String(index),
    route: routeOf(item),
    late: typeof item.detail.delayMinutes === "number" ? item.detail.delayMinutes : null,
    ...(() => { const pick = pickOf({ label: "", detail: item.detail }); return pick ? { pick } : {}; })(),
  })));
}

function SearchPalette({ t, rail, query, onQuery, onClose, onOpen }: {
  t: ReturnType<typeof createTranslator>;
  rail: readonly HorizonRailCard[];
  query: string;
  onQuery: (value: string) => void;
  onClose: () => void;
  onOpen: (key: string) => void;
}) {
  const jumps = STATUS_ORDER
    .filter((id) => id !== "absences")
    .map((id) => ({ id, label: opsStatusTitle(id, t) }))
    .filter((row) => {
      const q = query.trim().toLowerCase();
      return q === "" || row.label.toLowerCase().includes(q);
    });
  return (
    <div className="ops-horizon-scrim" onClick={onClose}>
      <div className="ops-horizon-dialog" role="dialog" aria-label={t("launchpad.board.search")} onClick={(event) => event.stopPropagation()}>
        <input
          autoFocus
          aria-label={t("launchpad.board.search")}
          placeholder={t("launchpad.board.palettePlaceholder")}
          value={query}
          onChange={(event) => onQuery(event.target.value)}
        />
        {jumps.map((row) => {
          const off = railOff(row.id, rail);
          return (
            <button key={row.id} type="button" className="ops-horizon-jump" disabled={off} onClick={() => onOpen(row.id)}>
              <span>{row.label}</span>
              <span>{off ? t(unavailableLabelKey(rail.find((card) => card.key === row.id)?.reason)) : t("launchpad.board.paletteOpen")}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { addLocalDays, createTranslator, epochOf, formatInstant, formatLocalWeekdayDay, localDateInZone, localDaysBetween, localMinuteOfDay, zoneCity } from "@dcortex/canvas-format";
import type { ApiClient } from "../api/client.js";
import { DeskNotesPopup, type NotesRead } from "../desk/DeskNotesPopup.js";
import type { ShiftHandoverResponse } from "../desk/briefModel.js";
import type { FlightPick } from "../desk/flightPick.js";
import { mergeNotes, type MemosResponse } from "../desk/notesModel.js";
import { LaunchpadFlightCard } from "../launchpad/LaunchpadFlightCard.js";
import { messages } from "../i18n/messages.js";
import { opsRank, opsStatusTitle, rawNocRanks, StatusDialog } from "./horizonStatus.js";
import { greetingKey, STATUS_ORDER, unavailableLabelKey } from "../launchpad/boardModel.js";
import { LAUNCHPAD_POLL_MS } from "../launchpad/horizonModel.js";
import type { HorizonItem, HorizonRailCard, HorizonResponse } from "../launchpad/types.js";

/** Ops Launchpad (knowledge-base/features/launchpad.md). The horizon snapshot as count marks.
 * Title, day controls, and the time rail share one box. Delay, summary, and Up next stack under it.
 * Zoom fills a fixed viewport the way the legacy board does: − shows more hours, Expand grows the lanes. */

const LANES = ["checkin", "uncrewed", "connection", "delayed", "ftl"] as const;
const DAY_OFFSETS = [-3, -2, -1, 0, 1, 2, 3, 4];
const HEAD = 36;
const PAD = 24;
const VIEWPORT_FALLBACK = 800;
/** Compact lane pitch, and the expanded pitch (legacy's ~2.5×). */
const LANE_COMPACT = 48;
const LANE_EXPANDED = 140;

interface ZoomLevel {
  visibleHours: number;
  windowMins: number;
  label: "hours" | "quarterDay" | "halfDay" | "day" | "twoDays" | "threeDays" | "week";
  tickHours: number;
  spanDays?: number;
}

const ZOOMS: readonly ZoomLevel[] = [
  { visibleHours: 8, windowMins: 12, label: "hours", tickHours: 2 },
  { visibleHours: 16, windowMins: 24, label: "hours", tickHours: 3 },
  { visibleHours: 24, windowMins: 360, label: "quarterDay", tickHours: 6 },
  { visibleHours: 48, windowMins: 720, label: "halfDay", tickHours: 12 },
  { visibleHours: 24, windowMins: 1440, label: "day", tickHours: 24 },
  { visibleHours: 48, windowMins: 1440, label: "twoDays", tickHours: 24, spanDays: 2 },
  { visibleHours: 72, windowMins: 1440, label: "threeDays", tickHours: 24, spanDays: 3 },
  { visibleHours: 168, windowMins: 1440, label: "week", tickHours: 24, spanDays: 7 },
];

function spanOf(zoom: ZoomLevel): number {
  return zoom.spanDays ?? 1;
}

function isHorizon(body: unknown): body is HorizonResponse {
  if (body == null || typeof body !== "object") return false;
  const row = body as HorizonResponse;
  return typeof row.date === "string" && typeof row.now === "string" && typeof row.zone === "string"
    && Array.isArray(row.wire) && Array.isArray(row.rail) && Array.isArray(row.queue) && Array.isArray(row.banks);
}

function routeOf(item: { detail: Record<string, unknown> }): string {
  const { dep, arr } = item.detail;
  return typeof dep === "string" && typeof arr === "string" ? `${dep}→${arr}` : "";
}

function flightOf(item: { label: string; detail: Record<string, unknown> }): string {
  return typeof item.detail.flight === "string" && item.detail.flight !== "" ? item.detail.flight : item.label;
}

function hhmm(minute: number): string {
  const wrapped = ((minute % 1440) + 1440) % 1440;
  return `${String(Math.floor(wrapped / 60)).padStart(2, "0")}:${String(wrapped % 60).padStart(2, "0")}`;
}

/** The axis starts at midnight of the loaded window. Scale is the viewport divided by the hours in view. */
function axisOf(viewportW: number, visibleHours: number, spanHours: number): { pxPerHour: number; width: number } {
  const inView = Math.min(Math.max(visibleHours, 1), Math.max(spanHours, 1));
  const pxPerHour = Math.max(viewportW - PAD * 2, 1) / inView;
  return { pxPerHour, width: PAD * 2 + spanHours * pxPerHour };
}

function xOfMins(mins: number, pxPerHour: number): number {
  return PAD + (mins / 60) * pxPerHour;
}

function toneOf(items: readonly { hoursUntil: number; severity: HorizonItem["severity"] }[]): string {
  if (items.every((item) => item.hoursUntil < 0)) return "past";
  if (items.some((item) => item.severity === "crit")) return "crit";
  if (items.some((item) => item.severity === "warn")) return "warn";
  return "watch";
}

interface Mark {
  domain?: HorizonItem["domain"];
  severity: HorizonItem["severity"];
  anchor: string;
  overdue: boolean;
  hoursUntil: number;
  /** Minutes from midnight of the loaded window's first day. */
  atMins: number;
  bankId?: string | null;
  label: string;
  detail: HorizonItem["detail"];
}

interface Bubble { key: string; left: number; tone: string; items: Mark[] }

function onAxis(anchor: string, start: string, zone: string, days: number): number | null {
  const diff = localDaysBetween(start, localDateInZone(epochOf(anchor), zone));
  if (diff < 0 || diff >= days) return null;
  return diff * 1440 + localMinuteOfDay(anchor, zone);
}

/** Legality marks use the anchors the desk row already carries. */
function rowMarks(snap: HorizonResponse, key: "ftl"): Array<Omit<Mark, "atMins">> {
  const row = snap.rows?.find((entry) => entry.key === key);
  if (!row || row.status !== "ok") return [];
  const now = epochOf(snap.now);
  const marks: Array<Omit<Mark, "atMins">> = [];
  for (const cell of row.cells) {
    cell.items.forEach((item, index) => {
      const hoursUntil = (epochOf(item.anchor) - now) / 3_600_000;
      const flight = typeof item.detail.flight === "string" && item.detail.flight !== "" ? item.detail.flight : String(index);
      marks.push({
        severity: item.severity,
        anchor: item.anchor,
        overdue: hoursUntil < 0,
        hoursUntil,
        ...(cell.bankId !== "" ? { bankId: cell.bankId } : {}),
        label: `${key}:${flight}:${cell.bankId}:${index}`,
        detail: item.detail,
      });
    });
  }
  return marks;
}

function clusterLane(items: readonly Mark[], xOf: (mins: number) => number, windowMins: number): Bubble[] {
  const sorted = [...items].sort((a, b) => a.atMins - b.atMins);
  if (windowMins >= 360) {
    const buckets = new Map<number, Mark[]>();
    for (const item of sorted) {
      const idx = Math.floor(item.atMins / windowMins);
      const list = buckets.get(idx) ?? [];
      list.push(item);
      buckets.set(idx, list);
    }
    return [...buckets.entries()].sort((a, b) => a[0] - b[0]).map(([idx, group]) => ({
      key: group[0]!.label,
      left: xOf(idx * windowMins + windowMins / 2),
      tone: toneOf(group),
      items: group,
    }));
  }
  const out: Bubble[] = [];
  for (const item of sorted) {
    const prev = out.at(-1);
    const last = prev?.items.at(-1);
    if (prev && last && item.atMins - last.atMins <= windowMins) {
      prev.items.push(item);
      prev.left = prev.items.reduce((sum, row) => sum + xOf(row.atMins), 0) / prev.items.length;
      prev.tone = toneOf(prev.items);
    } else {
      out.push({ key: item.label, left: xOf(item.atMins), tone: toneOf([item]), items: [item] });
    }
  }
  return out;
}

export function Launchpad({ client, onPresentation }: { client: ApiClient; onPresentation?: () => void }) {
  const ctx = client.presentation() ?? { timezone: "UTC", locale: "en", currency: "USD" };
  const t = createTranslator(ctx.locale, messages);
  const [params, setParams] = useSearchParams();
  const date = params.get("date") ?? "";
  const [snap, setSnap] = useState<HorizonResponse | null>(null);
  const [extra, setExtra] = useState<HorizonResponse[]>([]);
  const [zoomIdx, setZoomIdx] = useState(1);
  const [rangeDays, setRangeDays] = useState(1);
  const [expanded, setExpanded] = useState(false);
  const [viewportW, setViewportW] = useState(VIEWPORT_FALLBACK);
  const [mode, setMode] = useState<"timeline" | "banks">("timeline");
  const [failed, setFailed] = useState(false);
  const [queueOpen, setQueueOpen] = useState(false);
  const [delayOpen, setDelayOpen] = useState(false);
  const [open, setOpen] = useState<{ key: string; top: number; left: number } | null>(null);
  const [reload, setReload] = useState(0);
  const [statusOpen, setStatusOpen] = useState<{ key: string; times: string[] | null } | null>(null);
  const [flightPick, setFlightPick] = useState<FlightPick | null>(null);
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [paletteQuery, setPaletteQuery] = useState("");
  const [notesOpen, setNotesOpen] = useState(false);
  const [notes, setNotes] = useState<NotesRead>({ status: "loading" });
  const scrollerRef = useRef<HTMLDivElement>(null);
  const followNow = useRef(true);
  const holdCenter = useRef<number | null>(null);
  const seenDate = useRef<string | null>(null);
  const zoom = ZOOMS[zoomIdx] ?? ZOOMS[1]!;
  const banksOk = spanOf(zoom) <= 1;

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setPaletteOpen((current) => !current);
      }
      if (event.key === "Escape") {
        setPaletteOpen(false);
        setFlightPick(null);
        setStatusOpen(null);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  useEffect(() => {
    if (!banksOk) setMode("timeline");
  }, [banksOk]);

  useEffect(() => {
    followNow.current = true;
  }, [date]);

  useEffect(() => {
    let live = true;
    let polling = false; // a poll tick is skipped while the last read is still out, so a slow read never stacks
    const load = () => {
      if (polling) return;
      polling = true;
      const q = date ? `?date=${encodeURIComponent(date)}` : "";
      void client.get<unknown>(`/api/read/horizon${q}`).then(async (body) => {
        if (!live) return;
        if (!isHorizon(body)) {
          setSnap(null);
          setExtra([]);
          setFailed(true);
          return;
        }
        const more: HorizonResponse[] = [];
        if (rangeDays > 1) {
          const rest = await Promise.all(Array.from({ length: rangeDays - 1 }, (_, index) => {
            const day = addLocalDays(body.date, index + 1);
            return client.get<unknown>(`/api/read/horizon?date=${encodeURIComponent(day)}`);
          }));
          if (!live) return;
          for (const row of rest) if (isHorizon(row)) more.push(row);
        }
        setFailed(false);
        setSnap(body);
        setExtra(more);
      }).catch((err: unknown) => {
        if (!live) return;
        if (err instanceof Error && err.message === "unauthenticated") return;
        setSnap(null);
        setExtra([]);
        setFailed(true);
      }).finally(() => {
        polling = false;
      });
    };
    load();
    const timer = setInterval(() => {
      if (document.visibilityState === "visible") load();
    }, LAUNCHPAD_POLL_MS);
    return () => {
      live = false;
      clearInterval(timer);
    };
  }, [client, date, rangeDays, reload]);

  useEffect(() => {
    if (snap) onPresentation?.();
  }, [snap, onPresentation]);

  const notesDate = date || snap?.date || "";
  useEffect(() => {
    if (!notesDate) return;
    let live = true;
    void Promise.all([
      client.get<unknown>(`/api/read/flight-memos?date=${encodeURIComponent(notesDate)}`).catch(() => undefined),
      client.get<unknown>("/api/read/shift-handover").catch(() => undefined),
    ]).then(([memos, brief]) => {
      if (!live) return;
      const memoBody = isMemos(memos) ? memos : undefined;
      const briefBody = isBrief(brief) ? brief : undefined;
      setNotes({
        status: "ok",
        ...(memoBody ? { memos: memoBody } : { memosFailed: true }),
        ...(briefBody ? { brief: briefBody } : { briefFailed: true }),
      });
    });
    return () => {
      live = false;
    };
  }, [client, notesDate, reload]);

  const notesCount = useMemo(() => {
    if (notes.status !== "ok" || notes.memosFailed || notes.briefFailed) return null;
    return mergeNotes({
      ...(notes.memos ? { memos: notes.memos } : {}),
      ...(notes.brief ? { brief: notes.brief } : {}),
    }, t).length;
  }, [notes, t]);

  const today = snap ? localDateInZone(epochOf(snap.now), snap.zone) : "";
  const start = snap?.date ?? "";
  const loaded = snap ? [snap, ...extra] : [];
  const queue = snap?.queue ?? [];
  const head = queue[0];
  const nowMinute = snap ? localMinuteOfDay(snap.now, snap.zone) : 0;
  const laneH = expanded ? LANE_EXPANDED : LANE_COMPACT;
  const spanHours = rangeDays * 24;
  const { pxPerHour, width } = axisOf(viewportW, zoom.visibleHours, spanHours);
  const xAt = (mins: number) => xOfMins(mins, pxPerHour);
  const showNow = snap ? (() => {
    const diff = localDaysBetween(start, today);
    return diff >= 0 && diff < rangeDays;
  })() : false;
  const nowX = showNow ? xAt(localDaysBetween(start, today) * 1440 + nowMinute) : 0;
  const height = HEAD + LANES.length * laneH;

  const locate = (item: Omit<Mark, "atMins">): Mark | null => {
    if (!snap) return null;
    const atMins = onAxis(item.anchor, start, snap.zone, rangeDays);
    return atMins == null ? null : { ...item, atMins };
  };
  const wire: Mark[] = [];
  for (const row of loaded) {
    for (const item of row.wire) {
      const placed = locate(item);
      if (placed) wire.push(placed);
    }
  }
  const deskFtl: Mark[] = [];
  for (const row of loaded) {
    for (const item of rowMarks(row, "ftl")) {
      const placed = locate(item);
      if (placed) deskFtl.push(placed);
    }
  }

  useLayoutEffect(() => {
    const el = scrollerRef.current;
    if (!el) return;
    const apply = () => {
      const next = el.clientWidth;
      if (next > 0) setViewportW((current) => (current === next ? current : next));
    };
    apply();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(apply);
    observer.observe(el);
    return () => observer.disconnect();
  }, [snap]);

  useEffect(() => {
    const el = scrollerRef.current;
    if (!el || !snap) return;
    const dayChanged = seenDate.current !== snap.date;
    seenDate.current = snap.date;
    const center = holdCenter.current;
    holdCenter.current = null;
    const place = () => {
      if (dayChanged && !showNow) {
        el.scrollLeft = 0;
        return;
      }
      if (followNow.current && showNow) {
        const view = el.clientWidth || viewportW;
        el.scrollLeft = Math.max(0, nowX - view * 0.2);
        return;
      }
      if (center != null) {
        const view = el.clientWidth || viewportW;
        el.scrollLeft = Math.max(0, xOfMins(center, pxPerHour) - view / 2);
      }
    };
    place();
    const frame = requestAnimationFrame(place);
    return () => cancelAnimationFrame(frame);
  }, [snap, nowX, showNow, viewportW, zoomIdx, mode, rangeDays, pxPerHour]);
  let days = today ? DAY_OFFSETS.map((offset) => addLocalDays(today, offset)) : [];
  if (snap && !days.includes(snap.date)) days = [...days, snap.date].sort();

  const pickDay = (day: string) => {
    setRangeDays(1);
    setParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set("date", day);
      return next;
    });
  };

  const stepZoom = (dir: 1 | -1) => {
    const next = Math.max(0, Math.min(zoomIdx + dir, ZOOMS.length - 1));
    if (next === zoomIdx) return;
    const el = scrollerRef.current;
    if (el && !(followNow.current && showNow)) {
      const view = el.clientWidth || viewportW;
      holdCenter.current = ((el.scrollLeft + view / 2 - PAD) / pxPerHour) * 60;
    }
    const span = spanOf(ZOOMS[next]!);
    setZoomIdx(next);
    if (dir > 0) setRangeDays((current) => Math.max(current, span));
  };

  const chip = (day: string): string => {
    if (day === today) return t("desk.date.today");
    if (today && day === addLocalDays(today, 1)) return t("desk.date.tomorrow");
    return formatLocalWeekdayDay(day, ctx.locale);
  };

  const laneOf = (domain: (typeof LANES)[number]): readonly Mark[] =>
    domain === "ftl" ? deskFtl : wire.filter((item) => item.domain === domain);

  const ticks: Array<{ key: string; x: number; label: string }> = [];
  if (snap && mode === "timeline") {
    for (let hour = zoom.tickHours; hour < spanHours; hour += zoom.tickHours) {
      if (hour % 24 === 0) continue;
      ticks.push({ key: String(hour), x: xAt(hour * 60), label: hhmm(hour * 60) });
    }
  }
  if (snap && mode === "banks") {
    for (let day = 0; day < rangeDays; day++) {
      for (const bank of snap.banks) {
        const end = bank.endMinute != null && bank.endMinute > bank.startMinute ? bank.endMinute : bank.startMinute + 60;
        const x = xAt(day * 1440 + (bank.startMinute + end) / 2);
        if (x < 0 || x > width) continue;
        ticks.push({ key: `${day}-${bank.id}`, x, label: bankLabel(bank.id) });
      }
    }
  }

  const bubbles = (domain: (typeof LANES)[number]): Bubble[] => {
    if (mode === "banks") {
      const groups = new Map<string, Mark[]>();
      for (const item of laneOf(domain)) {
        const day = Math.floor(item.atMins / 1440);
        const key = `${day}:${item.bankId ?? ""}`;
        const list = groups.get(key) ?? [];
        list.push(item);
        groups.set(key, list);
      }
      return [...groups.values()].map((group) => {
        const at = group.reduce((sum, item) => sum + item.atMins, 0) / group.length;
        return { key: group[0]!.label, left: xAt(at), tone: toneOf(group), items: group };
      });
    }
    return clusterLane(laneOf(domain), xAt, zoom.windowMins);
  };

  const openBubble = open && snap
    ? LANES.flatMap((domain) => bubbles(domain)).find((bubble) => bubble.key === open.key)
    : undefined;

  return (
    <section className="ops-horizon" data-testid="launchpad-screen" aria-label={t("ops.launchpad.horizon")}>
      {failed && !snap && <p role="alert">{t("ops.launchpad.failed")}</p>}
      {!failed && !snap && (
        <div className="ops-horizon-loading" data-testid="launchpad-loading" role="status" aria-live="polite" aria-busy="true">
          <p className="ops-loading-note">{t("ops.launchpad.loading")}</p>
          <div className="ops-horizon-board" aria-hidden="true">
            {LANES.map((lane) => (
              <span key={lane} className="ops-skel ops-skel--block" />
            ))}
          </div>
        </div>
      )}
      {snap && (
        <>
          <div className="ops-horizon-greet">
              <div>
                <h2>{t(greetingKey(nowMinute))}</h2>
                <div className="ops-horizon-sub">{[client.presentation()?.customerName, zoneCity(snap.zone, client.presentation()), formatInstant(snap.now, ctx, { style: "time" })].filter(Boolean).join(" · ")}</div>
              </div>
              <div className="ops-horizon-actions">
                <button type="button" onClick={() => setNotesOpen(true)}>
                  {t("desk.notes.button")}
                  {notesCount !== null && notesCount > 0 && <span className="ops-horizon-badge">{notesCount > 99 ? "99+" : notesCount}</span>}
                </button>
                <button type="button" data-testid="launchpad-search" onClick={() => setPaletteOpen(true)}>{t("launchpad.board.search")}</button>
                <button type="button" onClick={() => setReload((n) => n + 1)}>{t("launchpad.board.refresh")}</button>
              </div>
            </div>
          <div className="ops-horizon-split">
          <div className="ops-horizon-main" data-testid="launchpad-column">
          <section className="ops-horizon-board" data-testid="launchpad-board">
            <div className="ops-horizon-head">
              <h1>{t("ops.launchpad.horizon")}</h1>
              <span className="ops-horizon-live">{t("ops.launchpad.live")} · {hhmm(nowMinute)}</span>
            </div>
            <div className="ops-horizon-tools" data-testid="launchpad-toolbar">
              <div className="ops-horizon-days" role="group" aria-label={t("ops.launchpad.pickDate")}>
                {days.map((day) => (
                  <button key={day} type="button" data-testid={`launchpad-day-${day}`} aria-pressed={day === snap.date} onClick={() => pickDay(day)}>
                    {chip(day)}
                  </button>
                ))}
                <label className="ops-horizon-cal">
                  <input
                    type="date"
                    data-testid="launchpad-date"
                    aria-label={t("ops.launchpad.pickDate")}
                    value={snap.date}
                    onChange={(event) => {
                      if (event.target.value) pickDay(event.target.value);
                    }}
                  />
                </label>
              </div>
              <div className="ops-horizon-modes" role="group">
                <button type="button" aria-pressed={mode === "timeline"} onClick={() => setMode("timeline")}>{t("ops.launchpad.timeline")}</button>
                <button type="button" aria-pressed={mode === "banks"} disabled={!banksOk} onClick={() => setMode("banks")}>{t("ops.launchpad.banks")}</button>
              </div>
              <div className="ops-horizon-stepper">
                <button type="button" aria-label={t("ops.launchpad.zoomOut")} disabled={zoomIdx >= ZOOMS.length - 1} onClick={() => stepZoom(1)}>−</button>
                <span data-testid="launchpad-zoom-label">{t(`ops.launchpad.zoom.${zoom.label}`)}</span>
                <button type="button" aria-label={t("ops.launchpad.zoomIn")} disabled={zoomIdx <= 0} onClick={() => stepZoom(-1)}>+</button>
              </div>
              <button type="button" className="ops-horizon-expand" aria-pressed={expanded} onClick={() => setExpanded((current) => !current)}>
                {expanded ? t("ops.launchpad.collapse") : t("ops.launchpad.expand")}
              </button>
            </div>
            <div className="ops-horizon-wire" data-testid="launchpad-wire">
              <div className="ops-horizon-gutter" style={{ height }}>
                {LANES.map((domain, index) => (
                  <div key={domain} className="ops-horizon-lane-name" data-testid={`launchpad-lane-${domain}`} style={{ top: HEAD + index * laneH + laneH / 2 - 8 }}>
                    {t(`ops.launchpad.lane.${domain}`)}
                  </div>
                ))}
              </div>
              <div
                className="ops-horizon-scroll"
                ref={scrollerRef}
                data-testid="launchpad-scroll"
                data-viewport={viewportW}
                onScroll={(event) => {
                  if (!showNow) return;
                  const el = event.currentTarget;
                  const view = el.clientWidth || viewportW;
                  const target = Math.max(0, nowX - view * 0.2);
                  if (Math.abs(el.scrollLeft - target) > 16) followNow.current = false;
                }}
              >
                <div className={`ops-horizon-plot${expanded ? " expanded" : ""}`} data-testid="launchpad-plot" style={{ height, width }}>
                  {Array.from({ length: rangeDays }, (_, day) => snap.banks.map((bank, index) => {
                    const end = bank.endMinute ?? bank.startMinute;
                    const left = xAt(day * 1440 + bank.startMinute);
                    let right = xAt(day * 1440 + end);
                    if (right <= left) right = xAt(day * 1440 + end + 1440);
                    const x = Math.max(0, left);
                    const w = Math.min(width, right) - x;
                    if (w <= 0) return null;
                    return <div key={`${day}-${bank.id}`} className={index % 2 ? "ops-horizon-band alt" : "ops-horizon-band"} style={{ left: x, width: w, top: HEAD }} />;
                  }))}
                  {mode === "timeline" && Array.from({ length: rangeDays }, (_, day) => (
                    <span key={`day-${day}`} className="ops-horizon-daytick" data-testid={`launchpad-daytick-${day}`} style={{ left: xAt(day * 1440) }}>
                      {formatLocalWeekdayDay(addLocalDays(start, day), ctx.locale)}
                    </span>
                  ))}
                  {ticks.map((mark) => (
                    <span key={mark.key} className="ops-horizon-tick" style={{ left: mark.x }}>{mark.label}</span>
                  ))}
                  {showNow && <div className="ops-horizon-past" style={{ top: HEAD, width: Math.max(0, Math.min(width, nowX)) }} />}
                  {LANES.map((domain, index) => (
                    <div key={domain} className="ops-horizon-line" style={{ top: HEAD + index * laneH + laneH / 2 }} />
                  ))}
                  {showNow && (
                    <div className="ops-horizon-now" style={{ left: nowX }} data-testid="launchpad-now">
                      <span className="ops-horizon-nowtag">{t("launchpad.now")} {hhmm(nowMinute)}</span>
                    </div>
                  )}
                  {LANES.map((domain, index) => bubbles(domain).map((bubble) => (
                    <button
                      key={bubble.key}
                      type="button"
                      className={`ops-horizon-dot ${bubble.tone}`}
                      data-testid={`launchpad-pill-${bubble.items[0]?.label ?? bubble.key}`}
                      style={{ left: bubble.left, top: HEAD + index * laneH + laneH / 2 - 13 }}
                      aria-label={tipLines(bubble.items, snap.zone, t).map((line) => line.detail !== "" ? `${line.title} — ${line.detail}` : line.title).join(", ")}
                      onMouseEnter={(event) => {
                        const rect = event.currentTarget.getBoundingClientRect();
                        setOpen({ key: bubble.key, top: rect.top, left: rect.left + rect.width / 2 });
                      }}
                      onMouseLeave={() => setOpen((current) => current?.key === bubble.key ? null : current)}
                      onFocus={(event) => {
                        const rect = event.currentTarget.getBoundingClientRect();
                        setOpen({ key: bubble.key, top: rect.top, left: rect.left + rect.width / 2 });
                      }}
                      onBlur={() => setOpen((current) => current?.key === bubble.key ? null : current)}
                      onClick={() => {
                        setOpen(null);
                        const at = domain === "checkin" || domain === "ftl"
                          ? [...new Set(bubble.items.map((item) => hhmm(localMinuteOfDay(item.anchor, snap.zone))))]
                          : null;
                        setStatusOpen({ key: domain, times: at });
                      }}
                    >
                      {bubble.items.length}
                    </button>
                  )))}
                </div>
              </div>
            </div>
            <div className="ops-horizon-legend">
              <span><i className="crit" />{t("ops.launchpad.actNow")}</span>
              <span><i className="warn" />{t("ops.launchpad.keepEye")}</span>
            </div>
          </section>
          <section className="ops-horizon-delay" data-testid="launchpad-delay" aria-label={t("ops.launchpad.delayRail")}>
            <button type="button" className="ops-horizon-next-toggle" aria-expanded={delayOpen} onClick={() => setDelayOpen((current) => !current)}>
              <span className="ops-horizon-up">{t("ops.launchpad.delayRail")}</span>
              <span className="ops-horizon-rank">{delayedRows(snap).length}</span>
              <span className="ops-horizon-chevron" aria-hidden="true">{delayOpen ? "▾" : "▸"}</span>
            </button>
            {delayOpen && (
              <div className="ops-horizon-delay-list">
                {delayedRows(snap).map((item) => (
                  <button key={item.key} type="button" className="ops-horizon-delay-row" onClick={() => item.pick && setFlightPick(item.pick)}>
                    <span>{item.flight}{item.route ? ` ${item.route}` : ""}</span>
                    {item.late != null && <span>{t("ops.launchpad.minutesLate", { n: String(item.late) })}</span>}
                  </button>
                ))}
              </div>
            )}
          </section>
          <section className="ops-horizon-summary">
            <h2>{t("ops.launchpad.summary")}</h2>
            <p>
              {head
                ? t("ops.launchpad.summaryBody", { n: String(queue.length), flight: `${flightOf(head)}${routeOf(head) ? ` ${routeOf(head)}` : ""}` })
                : t("ops.launchpad.summaryClear")}
            </p>
            {(snap.unplaced?.undated ?? 0) > 0 && (
              <p className="ops-horizon-note" data-testid="launchpad-undated">{t("ops.launchpad.undated", { n: snap.unplaced.undated })}</p>
            )}
          </section>
          <footer className="ops-horizon-next" data-testid="launchpad-next">
            <button type="button" className="ops-horizon-next-toggle" aria-expanded={queueOpen} onClick={() => setQueueOpen((current) => !current)}>
              <span className="ops-horizon-up">{t("ops.launchpad.upNext")}</span>
              <span className="ops-horizon-count">{queue.length}</span>
              {head && (
                <span>
                  {t("ops.launchpad.nextItem", {
                    when: hhmm(localMinuteOfDay(head.anchor, snap.zone)),
                    flight: `${flightOf(head)}${routeOf(head) ? ` · ${routeOf(head)}` : ""}`,
                  })}
                  {head.overdue ? ` · ${t("launchpad.overdue")}` : ""}
                </span>
              )}
              <span className="ops-horizon-rank">{t("ops.launchpad.rankBy")}</span>
              <span className="ops-horizon-chevron" aria-hidden="true">{queueOpen ? "▾" : "▸"}</span>
            </button>
            {queueOpen && (
              <ul>
                {queue.map((item) => (
                  <li key={item.label} data-testid={`launchpad-next-${item.label}`}>
                    <b>{flightOf(item)}{routeOf(item) ? ` ${routeOf(item)}` : ""}</b>
                    <span>{hhmm(localMinuteOfDay(item.anchor, snap.zone))}{item.overdue ? ` · ${t("launchpad.overdue")}` : ""}</span>
                  </li>
                ))}
              </ul>
            )}
          </footer>
          </div>
          <aside className="ops-horizon-status" aria-label={t("launchpad.rail")}>
            {STATUS_ORDER.filter((key) => key !== "absences" && snap.rail.some((card) => card.key === key)).map((key) => {
              const card = snap.rail.find((row) => row.key === key);
              return (
                <button key={key} type="button" className="ops-horizon-kpi" data-testid={`launchpad-status-${key}`} onClick={() => setStatusOpen({ key, times: null })}>
                  <span className="ops-horizon-kpi-title">{opsStatusTitle(key, t)}</span>
                  <span className="ops-horizon-kpi-value">{card?.status === "ok" ? card.count ?? 0 : t(unavailableLabelKey(card?.reason))}</span>
                  <span className="ops-horizon-kpi-foot">{card?.status === "ok" ? t("ops.launchpad.onDay") : card?.reason === "failed" || card?.reason === "not_permitted" ? t(unavailableLabelKey(card.reason)) : t("ops.launchpad.sourceOff")}</span>
                </button>
              );
            })}
          </aside>
          </div>
          {statusOpen && (
            <StatusDialog key={statusOpen.key} t={t} client={client} snap={snap} statusKey={statusOpen.key} times={statusOpen.times} onClose={() => setStatusOpen(null)} onFlight={setFlightPick} />
          )}
          {flightPick && (
            <LaunchpadFlightCard client={client} pick={flightPick} date={snap.date} zone={snap.zone} ctx={ctx} t={t} onClose={() => setFlightPick(null)} />
          )}
          {paletteOpen && (
            <SearchPalette
              t={t}
              rail={snap.rail}
              query={paletteQuery}
              onQuery={setPaletteQuery}
              onClose={() => setPaletteOpen(false)}
              onOpen={(key) => { setPaletteOpen(false); setPaletteQuery(""); setStatusOpen({ key, times: null }); }}
            />
          )}
          {notesOpen && (
            <DeskNotesPopup
              read={notes}
              date={notesDate}
              banks={snap.banks.map((bank) => ({ id: bank.id, startMinute: bank.startMinute, endMinute: bank.endMinute ?? bank.startMinute }))}
              ctx={ctx}
              t={t}
              onClose={() => setNotesOpen(false)}
            />
          )}
          {open && openBubble && (
            <WireTip bubble={openBubble} zone={snap.zone} top={open.top} left={open.left} t={t} />
          )}
        </>
      )}
    </section>
  );
}

function bankLabel(id: string): string {
  const match = /^B(\d+)$/.exec(id);
  return match ? `Bank ${match[1]}` : id;
}

/** The stored label is an opaque key. The card is the time, the lane, and the detail fields. */
function WireTip({ bubble, zone, top, left, t }: {
  bubble: Bubble;
  zone: string;
  top: number;
  left: number;
  t: (key: string, params?: Record<string, string | number>) => string;
}) {
  const items = [...bubble.items].sort((a, b) => a.atMins - b.atMins);
  const first = items[0];
  if (!first) return null;
  const domain = kindOf(first);
  const lines = tipLines(items, zone, t);
  const bankIds = [...new Set(items.flatMap((item) => (item.bankId ? [item.bankId] : [])))];
  const bank = bankIds.length === 1 ? bankLabel(bankIds[0]!) : "";
  const shown = lines.slice(0, 4);
  const more = lines.length - shown.length;
  const count = domain === "uncrewed" ? openSeats(items) : items.length;
  const head = [bank, t(`ops.launchpad.lane.${domain}`), String(count)].filter((part) => part !== "").join(" · ");
  return (
    <div className="ops-horizon-pop" role="tooltip" style={{ top, left }}>
      <div className="tt-head">
        <span className={`tt-time ${bubble.tone}`}>{hhmm(localMinuteOfDay(first.anchor, zone))}</span>
        <span>{head}</span>
      </div>
      {shown.map((line, index) => (
          <div className="tt-row" key={`${line.title}:${index}`}>
            <b>{line.title}</b>
            {line.detail !== "" ? ` — ${line.detail}` : ""}
          </div>
      ))}
      {more > 0 && <div className="tt-more">{t("ops.launchpad.tip.more", { n: String(more) })}</div>}
    </div>
  );
}

function kindOf(item: Mark): string {
  return item.domain ?? field(item.detail, "kind");
}

function field(detail: Record<string, unknown>, key: string): string {
  const value = detail[key];
  return typeof value === "string" ? value : "";
}

function fieldNum(detail: Record<string, unknown>, key: string): number | null {
  const value = detail[key];
  return typeof value === "number" ? value : null;
}

function readable(label: string): string {
  return /^(uncrewed|connection|checkin|delayed|ftl):/.test(label) ? "" : label;
}

function joinTime(lead: string, time: string, rest: string): string {
  const head = [lead, time].filter((part) => part !== "").join(" ");
  return [head, rest].filter((part) => part !== "").join(" · ");
}

interface SeatBit { code: string; short: number | null }

function seatsOf(detail: Record<string, unknown>): SeatBit[] {
  const seats = detail.seats;
  if (Array.isArray(seats)) {
    return seats.filter((row): row is Record<string, unknown> => !!row && typeof row === "object").map((row) => ({
      code: field(row, "code") || field(row, "positionCode"),
      short: fieldNum(row, "short"),
    })).filter((row) => row.code !== "");
  }
  const code = field(detail, "positionCode");
  return code === "" ? [] : [{ code, short: fieldNum(detail, "short") }];
}

function groupUncrewed(items: readonly Mark[]): Mark[] {
  const out: Mark[] = [];
  const index = new Map<string, number>();
  for (const item of items) {
    const flight = field(item.detail, "flight");
    const dep = field(item.detail, "dep");
    const arr = field(item.detail, "arr");
    const route = flight !== "" || dep !== "" || arr !== ""
      ? `${flight}|${dep}|${arr}`
      : field(item.detail, "pairingId") || field(item.detail, "pairingKey") || item.label;
    const key = `${route}|${Math.floor(item.atMins)}`;
    const at = index.get(key);
    const bits = seatsOf(item.detail);
    if (at == null) {
      index.set(key, out.length);
      out.push({ ...item, detail: { ...item.detail, seats: bits } });
      continue;
    }
    const prev = out[at]!;
    prev.detail = { ...prev.detail, seats: [...seatsOf(prev.detail), ...bits] };
  }
  return out;
}

function openSeats(items: readonly Mark[]): number {
  return items.reduce((sum, item) => {
    const seats = seatsOf(item.detail);
    if (seats.length === 0) return sum + 1;
    return sum + seats.reduce((n, seat) => n + (seat.short != null && seat.short > 0 ? seat.short : 1), 0);
  }, 0);
}

function tipLines(items: readonly Mark[], zone: string, t: (key: string, params?: Record<string, string | number>) => string): Array<{ title: string; detail: string }> {
  const rows = items[0] && kindOf(items[0]) === "uncrewed" ? groupUncrewed(items) : items;
  return rows.map((item) => tipOf(item, hhmm(localMinuteOfDay(item.anchor, zone)), t));
}

function tipOf(item: Mark, time: string, t: (key: string, params?: Record<string, string | number>) => string): { title: string; detail: string } {
  const detail = item.detail;
  const kind = kindOf(item);
  if (kind === "uncrewed") {
    const flight = field(detail, "flight");
    const dep = field(detail, "dep");
    const arr = field(detail, "arr");
    const seats = seatsOf(detail);
    const raw = rawNocRanks(seats.map((seat) => seat.code));
    const what = seats.map((seat) => {
      const rank = opsRank(seat.code, raw);
      if (!rank) return "";
      const n = seat.short != null && seat.short > 0 ? seat.short : 1;
      return `${rank} −${n}`;
    }).filter((part) => part !== "").join(", ");
    const route = dep !== "" && arr !== "" ? `${dep} → ${arr}` : "";
    const lead = [flight, time].filter((part) => part !== "").join(" ");
    return { title: [lead, route].filter((part) => part !== "").join(" · "), detail: what !== "" ? t("ops.launchpad.tip.needs", { what }) : "" };
  }
  if (kind === "connection") {
    const inbound = field(detail, "inboundFlight");
    const outbound = field(detail, "outboundFlight");
    const station = field(detail, "connectionStation");
    const hop = [inbound, outbound].filter((part) => part !== "").join(" → ");
    const named = readable(item.label);
    const title = hop !== ""
      ? `${hop} ${time}${station !== "" ? ` · ${station}` : ""}`
      : joinTime(named, time, named === "" ? field(detail, "pairingRoute") : "");
    const status = t(item.severity === "crit" ? "ops.launchpad.tip.critical" : "ops.launchpad.tip.warning");
    const actual = fieldNum(detail, "actualGapMins");
    const required = fieldNum(detail, "requiredMins");
    const gap = actual != null && required != null ? t("ops.launchpad.tip.gap", { actual: String(actual), required: String(required) }) : "";
    const line = [t("ops.launchpad.tip.connection", { status }), gap].filter((part) => part !== "").join(" · ");
    return { title, detail: line };
  }
  if (kind === "checkin") {
    const who = [field(detail, "position"), field(detail, "displayName")].filter((part) => part !== "").join(" ");
    const late = fieldNum(detail, "lateMinutes");
    const parts = [
      ...(who !== "" ? [t("ops.launchpad.tip.notCheckedIn", { who })] : []),
      ...(late != null ? [t("ops.launchpad.minutesLate", { n: String(late) })] : []),
    ];
    return { title: joinTime(field(detail, "flight") || readable(item.label), time, routeOf(item)), detail: parts.join(" · ") };
  }
  if (kind === "delayed") {
    const late = fieldNum(detail, "delayMinutes");
    return {
      title: joinTime(field(detail, "flight") || readable(item.label), time, routeOf(item)),
      detail: late != null ? t("ops.launchpad.minutesLate", { n: String(late) }) : "",
    };
  }
  const who = [field(detail, "role"), field(detail, "displayName")].filter((part) => part !== "").join(" · ");
  const current = fieldNum(detail, "currentValue");
  const limit = fieldNum(detail, "limitValue");
  const unit = field(detail, "unit");
  const headroom = current != null && limit != null ? `${current}/${limit}${unit !== "" ? ` ${unit}` : ""}` : "";
  const line = [field(detail, "ruleCode"), headroom, field(detail, "windowType")].filter((part) => part !== "").join(" · ");
  const title = who !== "" ? who : joinTime(field(detail, "flight") || readable(item.label), time, routeOf(item));
  return { title, detail: line };
}

function isMemos(body: unknown): body is MemosResponse {
  return !!body && typeof body === "object" && Array.isArray((body as MemosResponse).memos);
}

function isBrief(body: unknown): body is ShiftHandoverResponse {
  return !!body && typeof body === "object" && Array.isArray((body as ShiftHandoverResponse).sections);
}

function railOff(key: string, rail: readonly HorizonRailCard[]): boolean {
  const card = rail.find((row) => row.key === key);
  return !card || card.status !== "ok";
}

function text(value: unknown): string {
  return typeof value === "string" && value !== "" ? value : "";
}

function pickOf(item: { label: string; detail: Record<string, unknown> }): FlightPick | undefined {
  const flight = text(item.detail.outboundFlight) || text(item.detail.flight) || (item.label.includes(":") ? "" : item.label);
  const dep = text(item.detail.connectionStation) || text(item.detail.dep);
  const arr = text(item.detail.arr);
  if (!flight || !dep || !arr) return undefined;
  const legId = text(item.detail.legId);
  return { flight, dep, arr, ...(legId ? { legId } : {}) };
}

function delayedRows(snap: HorizonResponse): Array<{ key: string; flight: string; route: string; late: number | null; pick?: FlightPick }> {
  const fromWire = snap.wire.filter((item) => item.domain === "delayed").map((item) => ({
    key: item.label,
    flight: flightOf(item),
    route: routeOf(item),
    late: typeof item.detail.delayMinutes === "number" ? item.detail.delayMinutes : null,
    ...(() => { const pick = pickOf(item); return pick ? { pick } : {}; })(),
  }));
  if (fromWire.length > 0) return fromWire;
  const row = snap.rows?.find((entry) => entry.key === "delayed");
  if (!row || row.status !== "ok") return [];
  return row.cells.flatMap((cell, cellIndex) => cell.items.map((item, index) => ({
    key: `${cell.bankId}:${cellIndex}:${index}`,
    flight: typeof item.detail.flight === "string" && item.detail.flight !== "" ? item.detail.flight : String(index),
    route: routeOf(item),
    late: typeof item.detail.delayMinutes === "number" ? item.detail.delayMinutes : null,
    ...(() => { const pick = pickOf({ label: "", detail: item.detail }); return pick ? { pick } : {}; })(),
  })));
}

function SearchPalette({ t, rail, query, onQuery, onClose, onOpen }: {
  t: ReturnType<typeof createTranslator>;
  rail: readonly HorizonRailCard[];
  query: string;
  onQuery: (value: string) => void;
  onClose: () => void;
  onOpen: (key: string) => void;
}) {
  const jumps = STATUS_ORDER
    .filter((id) => id !== "absences")
    .map((id) => ({ id, label: opsStatusTitle(id, t) }))
    .filter((row) => {
      const q = query.trim().toLowerCase();
      return q === "" || row.label.toLowerCase().includes(q);
    });
  return (
    <div className="ops-horizon-scrim" onClick={onClose}>
      <div className="ops-horizon-dialog" role="dialog" aria-label={t("launchpad.board.search")} onClick={(event) => event.stopPropagation()}>
        <input
          autoFocus
          aria-label={t("launchpad.board.search")}
          placeholder={t("launchpad.board.palettePlaceholder")}
          value={query}
          onChange={(event) => onQuery(event.target.value)}
        />
        {jumps.map((row) => {
          const off = railOff(row.id, rail);
          return (
            <button key={row.id} type="button" className="ops-horizon-jump" disabled={off} onClick={() => onOpen(row.id)}>
              <span>{row.label}</span>
              <span>{off ? t(unavailableLabelKey(rail.find((card) => card.key === row.id)?.reason)) : t("launchpad.board.paletteOpen")}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

